import pathlib,json,gzip,statistics,re,html,shutil
from PIL import Image,ImageDraw
root=pathlib.Path('docs/mission-12-evidence/nature')
before=json.loads((root/'before.json').read_text());after=json.loads((root/'after.json').read_text())
perf=json.loads(gzip.decompress((root/'performance.json.gz').read_bytes()))
catalog=json.loads(pathlib.Path('public/materials/nature/catalog.json').read_text())
buffers=json.loads((root/'buffers.json').read_text())
titles={'bois':'Sous les couronnes','aerienne':'La forêt depuis le ciel','lisiere':'Une lisière irrégulière','sous-bois':'Au pied des arbres','berge':'La végétation près de l’eau','prairie':'Une prairie cartographiée','vent-modere':'Un vent modéré','rafales':'Le régime orageux et ses rafales','printemps':'Les nuances du printemps','automne':'Des automnes différents','hiver':'Les branches en hiver','persistants':'Les conifères en hiver'}
metrics=[]
for profile in ['eco','balanced','quality']:
 for station in ['bois','aerienne','sous-bois','prairie']:
  rows={phase:[r for r in perf['rows'] if r['profile']==profile and r['station']==station and r['phase']==phase] for phase in ['before','after']}
  med={phase:statistics.median(x['ms'] for r in rows[phase] for x in r['samples']) for phase in rows}
  spread={phase:statistics.quantiles([x['ms'] for r in rows[phase] for x in r['samples']],n=4,method='inclusive') for phase in rows}
  a,b=[rows[k][-1] for k in ['before','after']]
  metrics.append({'profile':profile,'station':station,'beforeMs':med['before'],'afterMs':med['after'],'changePercent':(med['after']/med['before']-1)*100,'beforeIQRMs':[spread['before'][0],spread['before'][2]],'afterIQRMs':[spread['after'][0],spread['after'][2]],'callsBefore':a['samples'][0]['calls'],'callsAfter':b['samples'][0]['calls'],'trianglesBefore':a['samples'][0]['triangles'],'trianglesAfter':b['samples'][0]['triangles'],'texturesBefore':a['state']['textures'],'texturesAfter':b['state']['textures']})
summary={'base':'96c824a2a2d5220d69d31c503dde82ed154e3db6','environment':perf['environment'],'rows':metrics,'texturePNGBytes':catalog['bytes'],'additionalTextureEstimateWithMipsBytes':256*256*4*4/3,'buffers':buffers,'interpretation':'Synchronous SwiftShader render/readback times, not hardware FPS or Android performance. Geometry and LOD intentionally change; both draw inventories are retained. Heap snapshots in the raw trace do not measure GPU allocation.'}
(root/'summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n')
cards=[]
for a,b in zip(before['results'],after['results']):
 assert a['station']==b['station'] and a['state']['matrix']==b['state']['matrix'] and a['state']['climate']['date']==b['state']['climate']['date'] and a['state']['climate']['weather']==b['state']['climate']['weather']
 name=a['id'];title=titles[name];board=Image.new('RGB',(1920,680),'#101c19');d=ImageDraw.Draw(board)
 for i,(phase,label) in enumerate([('before','Jalon B · avant'),('after','Jalon C · après')]):
  d.text((20+i*960,12),label,fill='#e7e2cc');board.paste(Image.open(root/f'{phase}-{name}.jpg'),(i*960,40))
 board.save(root/f'compare-{name}.jpg',quality=88,optimize=True)
 family='saisons' if name in ['printemps','automne','hiver','persistants'] else 'vent' if name in ['vent-modere','rafales'] else 'paysages'
 images=''.join(f'<figure><a href="{phase}-{name}.jpg" target="_blank"><img loading="lazy" src="{phase}-{name}.jpg" alt="{html.escape(title)} — {label}"></a><figcaption>{label}</figcaption></figure>' for phase,label in [('before','Avant · Jalon B'),('after','Après · Jalon C')])
 cards.append(f'<article class="card" data-family="{family}"><h2>{title}</h2><p class="condition">Équilibré · 960 × 640 · {a["state"]["climate"]["date"]}</p><div class="pair">{images}</div><details><summary>Conditions de comparaison</summary><code>{html.escape(str(a["station"][1:]))}</code><p>Mêmes caméra, date, météo et profil. Les stations photographiques sont des poses de diagnostic ; leur présence ne documente pas un accès piéton réel.</p></details></article>')
table=''.join(f'<tr><th>{r["profile"]}</th><td>{titles[r["station"]]}</td><td>{r["beforeMs"]:.1f} → {r["afterMs"]:.1f}</td><td>{r["changePercent"]:+.1f} %</td><td>{r["callsBefore"]} → {r["callsAfter"]}</td><td>{r["trianglesBefore"]:,} → {r["trianglesAfter"]:,}</td></tr>' for r in metrics)
# A real alternative rendered through the same engine and station.
alt=json.loads(pathlib.Path('work/mission-12C/approaches/volume.json').read_text());v=alt['results'][0]
assert v['state']['matrix']==after['results'][0]['state']['matrix'] and v['state']['climate']['date']==after['results'][0]['state']['climate']['date'];assert not alt['errors']
shutil.copyfile('work/mission-12C/approaches/volume-bois.jpg',root/'approach-volume.jpg')
(root/'approaches.json').write_text(json.dumps({'method':'Same real engine, station, camera and calendar; test-only replacement of createTreeArt approach. Dedicated performance protocol is separate.','alternatives':{'volumes':{'nearTriangles':120,'image':'approach-volume.jpg','capture':v},'sprays':{'nearTriangles':84,'image':'after-bois.jpg'}},'decision':'Hybrid: original alpha-tested sprays nearby, opaque shared volumes far away and throughout Eco. Instancing retained. External library pages studied without importing individual models. Camera-facing impostors deferred because aerial and free walking views need stable parallax.'},ensure_ascii=False,indent=2))
css=re.search(r'<style>.*?</style>',pathlib.Path('docs/mission-12-evidence/index.html').read_text(),re.S).group()
page='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Endless Earth — Mission 12C</title>'''+css+'''
<header><div class="eyebrow">Endless Earth · Mission 12 · Jalon C</div><h1>Le feuillage s’ouvre,<br>le paysage respire.</h1><p>Des couronnes plus ajourées, des branches visibles en hiver et des détails de sous-bois différenciés. Même géographie, vent et calendrier partagés avec Mission 11.</p><span class="tag">Revue artistique attendue · D non commencé</span><p class="links"><a href="../../mission-12.md">Rapport et reproduction</a><a href="../architecture/index.html">Revoir B</a><a href="../index.html">Revoir A</a><a href="/endless-earth/?moment=afternoon&weather=clear">Jeu local</a></p></header>
<main><section><h2>Douze vues, des conditions identiques</h2><p>À gauche : B livré, commit 96c824a. À droite : C. Les 2 500 ancrages d’arbres, leurs tailles et classes sont conservés ; les individus et formes restent des interprétations dans des habitats cartographiés, sans inventaire botanique local.</p><nav aria-label="Filtrer les vues"><button data-filter="all" aria-pressed="true">Tout voir</button><button data-filter="paysages" aria-pressed="false">Paysages</button><button data-filter="saisons" aria-pressed="false">Saisons</button><button data-filter="vent" aria-pressed="false">Vent</button></nav>'''+''.join(cards)+'''
</section><section><h2>Le vent, vraiment enregistré</h2><p>Une inspection de forêt à une position compatible avec les collisions, puis les commandes ordinaires Ensoleillé → Nuageux → Orageux, onze secondes par régime. Le film et le son post-limiteur conservent leur durée réelle ; aucun ralenti, accélération ou mouvement de feuilles ajouté au montage. La machine utilise SwiftShader ; le nombre d’images reste celui réellement rendu.</p><div class="video-grid"><figure><video controls preload="metadata" src="before-vent.webm"></video><figcaption>Avant · B</figcaption></figure><figure><video controls preload="metadata" src="after-vent.webm"></video><figcaption>Après · C</figcaption></figure></div><p>Les graines et ancrages sont stables. Les films ne sont pas synchronisés image par image : le timestep plafonné et le coût logiciel font avancer la simulation différemment.</p></section>
<section><h2>Une promenade distincte</h2><p>Même contrôle automatique et mêmes voies OSM dans le village. Ces deux films ne documentent pas une liaison piétonne avec la station de forêt.</p><div class="video-grid"><figure><video controls preload="metadata" src="../architecture/after-promenade.webm"></video><figcaption>Référence B</figcaption></figure><figure><video controls preload="metadata" src="after-promenade.webm"></video><figcaption>C · promenade ordinaire avec collisions et son</figcaption></figure></div></section>
<section><h2>Choisir la forme selon la distance</h2><p>Deux approches procédurales ont été comparées dans le vrai moteur. Les bouquets ajourés sont retenus à proximité, avec 84 triangles par couronne ; les volumes partagés de 60 triangles restent au loin et dans Éco. Les branches de 40 triangles sont partagées, sans objet ou animation CPU par arbre. Les imposteurs orientés vers la caméra sont différés pour conserver une forme stable en marche et en vue aérienne.</p><div class="pair"><figure><img loading="lazy" src="approach-volume.jpg" alt="Variante à volumes procéduraux dans le moteur"><figcaption>Variante à volumes · 120 triangles proches</figcaption></figure><figure><img loading="lazy" src="after-bois.jpg" alt="Bouquets de feuilles retenus dans le moteur"><figcaption>Bouquets de feuilles retenus à proximité</figcaption></figure></div><p><a href="approaches.json">Protocole de sélection</a> · <a href="resources.json">Ressources étudiées</a> · <a href="/endless-earth/materials/nature/catalog.json">Familles, auteur et empreintes</a></p></section>
<section><h2>Le coût, mesuré</h2><p>288 rendus synchronisés, quatre vues, trois profils, trois passages avec ordre alterné. Médianes en millisecondes sous SwiftShader : <strong>ce ne sont pas des FPS sur GPU physique</strong>. Les géométries et LOD changent ; les inventaires des deux versions sont conservés.</p><div class="table"><table><thead><tr><th>Profil</th><th>Station</th><th>Avant → après ms</th><th>Écart</th><th>Appels</th><th>Triangles</th></tr></thead><tbody>'''+table+'''</tbody></table></div><p>Une texture originale partagée de 256² : au maximum +0,33 Mio estimé avec mipmaps. Éco ne l’échantillonne pas. Les couleurs des détails sont compactées sur huit bits ; les buffers et packs complets sont détaillés dans le rapport. Les détails ne sont pas tous chargés ensemble : le cache invisible reste limité à quatre cellules. GPU physique et Android restent à valider.</p><p><a href="summary.json">Synthèse</a> · <a href="performance.json.gz">Trace compressée</a> · <a href="buffers.json">Buffers</a> · <a href="runtime.json">Saisons, cache et secours</a></p></section>
<section class="note"><h2>À apprécier ensemble</h2><p>Les familles, le feuillage, les branches, les sous-bois et la réponse au vent sont implémentés et testés. Leur richesse, le caractère des silhouettes et la retenue du mouvement restent à votre appréciation. La ramification reste stylisée, les densités d’arbres antérieures sont conservées et le MNT à 10 m reste visible.</p><p>Le calendrier est une interprétation tempérée : pas de neige automatique, pas de botanique mesurée. Le maintien du feuillage des conifères est une hypothèse de famille ; les sources ne prouvent pas une espèce précise. Aucun animal, événement, son ou second système météorologique n’est ajouté.</p><p>Arrêt au Jalon C. La PR reste en brouillon, sans merge ni déploiement public. Votre accord est attendu avant D.</p></section><footer>IGN / ASP · Licence Ouverte 2.0 · © OpenStreetMap contributors · ODbL. Art végétal procédural original Endless Earth. Captures du vrai moteur.</footer></main><script>document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelectorAll('[data-family]').forEach(c=>c.hidden=b.dataset.filter!=='all'&&c.dataset.family!==b.dataset.filter)}));</script></html>'''
(root/'index.html').write_text(page)
print(json.dumps(summary,ensure_ascii=False))
